class Hero:
    def __init__(self, name):
        self.name = name
        self.bag = set()

    def pick(self, item):
        self.bag.add(item)
        return f"{self.name} picked up the {item}."

piko = Hero("Piko")
for item in ["map", "key", "map"]:
    print(piko.pick(item))
print("Bag:", sorted(piko.bag))

